import{_ as l,c as e,o as s,ag as a}from"./chunks/framework.DRADY2L-.js";const u=JSON.parse('{"title":"Web 安全","description":"","frontmatter":{},"headers":[],"relativePath":"front-end/web-security.md","filePath":"front-end/web-security.md","lastUpdated":1741596656000}'),t={name:"front-end/web-security.md"};function o(n,i,r,c,d,h){return s(),e("div",null,[...i[0]||(i[0]=[a(`<h1 id="web-安全" tabindex="-1">Web 安全 <a class="header-anchor" href="#web-安全" aria-label="Permalink to &quot;Web 安全&quot;">​</a></h1><h2 id="xss-跨站脚本攻击" tabindex="-1">XSS（跨站脚本攻击） <a class="header-anchor" href="#xss-跨站脚本攻击" aria-label="Permalink to &quot;XSS（跨站脚本攻击）&quot;">​</a></h2><ul><li>攻击者向网页注入恶意脚本，当用户浏览页面时，脚本在用户浏览器执行，窃取数据或发起攻击。</li><li>如何区分存储型/反射型/DOM 型 XSS？防御方案有哪些？ <ul><li><strong>类型</strong>： <ul><li><strong>存储型</strong>：恶意脚本存储到服务器（如评论区内容），所有访问者均受影响。</li><li><strong>反射型</strong>：恶意脚本通过 URL 参数注入（如钓鱼链接），需用户主动触发。</li><li><strong>DOM 型</strong>：前端直接操作 DOM 导致（如<code>innerHTML</code>），不经过服务端。</li></ul></li><li><strong>防御</strong>： <ul><li><strong>输入过滤</strong> + <strong>输出转义</strong>（将<code>&lt;</code>、<code>&gt;</code>转义为<code>&amp;lt;</code>、<code>&amp;gt;</code>）。</li><li>避免使用<code>innerHTML</code>，优先用<code>textContent</code>或<code>setAttribute</code>。</li><li>启用<strong>CSP 内容安全策略</strong>（限制脚本来源）。</li><li>Cookie 设置<code>HttpOnly</code>防止脚本窃取。</li></ul></li></ul></li></ul><h2 id="csrf-跨站请求伪造" tabindex="-1">CSRF（跨站请求伪造） <a class="header-anchor" href="#csrf-跨站请求伪造" aria-label="Permalink to &quot;CSRF（跨站请求伪造）&quot;">​</a></h2><ul><li>攻击者诱导用户访问恶意页面，伪造用户在已登录的站点发起非预期操作（如转账）。</li><li>CSRF 攻击流程是什么？如何防御？ <ul><li><strong>流程</strong>：用户登录 A 站 → 诱导访问 B 站 → B 站伪造 A 站请求（利用自动携带的 Cookie）。</li><li><strong>防御</strong>： <ul><li><strong>CSRF Token</strong>：服务端生成随机 Token，前端提交时携带并验证。</li><li>校验请求头<code>Origin/Referer</code>（禁止跨域请求）。</li><li>Cookie 设置<code>SameSite=Strict/Lax</code>（限制跨域携带 Cookie）。</li></ul></li></ul></li></ul><h2 id="点击劫持-clickjacking" tabindex="-1">点击劫持（Clickjacking） <a class="header-anchor" href="#点击劫持-clickjacking" aria-label="Permalink to &quot;点击劫持（Clickjacking）&quot;">​</a></h2><ul><li>攻击者将目标网站嵌入透明 iframe，诱导用户点击伪装按钮（如虚假关闭弹窗）。</li><li>如何防止页面被嵌入到 iframe 中攻击？ <ul><li><strong>服务端防御</strong>： <ul><li>设置响应头：<code>X-Frame-Options: DENY</code>（禁止嵌入）或<code>SAMEORIGIN</code>（仅同源）。</li><li>使用 CSP 的<code>frame-ancestors</code>指令（如<code>frame-ancestors &#39;none&#39;</code>）。</li></ul></li><li><strong>前端防御（辅助）</strong>：<div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (top </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window) top.location </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.location; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 非可靠，可被绕过</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul></li></ul><h2 id="csp-内容安全策略" tabindex="-1">CSP（内容安全策略） <a class="header-anchor" href="#csp-内容安全策略" aria-label="Permalink to &quot;CSP（内容安全策略）&quot;">​</a></h2><ul><li>通过 HTTP 响应头<code>Content-Security-Policy</code>限制页面资源加载来源，防止 XSS 和数据注入。</li><li>如何配置 CSP 策略？实际项目中如何平衡安全性与便利性？ <ul><li><strong>配置示例</strong>：<div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Security-Policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default-src &#39;self&#39;; script-src &#39;self&#39; https://trusted.cdn.com; style-src &#39;self&#39; &#39;unsafe-inline&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><strong>关键指令</strong>： <ul><li><code>default-src</code>：默认资源加载规则。</li><li><code>script-src</code>/<code>style-src</code>：限制脚本/样式来源（避免<code>&#39;unsafe-inline&#39;</code>）。</li><li><code>report-uri</code>：违规行为上报地址。</li></ul></li><li><strong>平衡策略</strong>： <ul><li>开发阶段启用<code>Content-Security-Policy-Report-Only</code>监控问题。</li><li>逐步替换内联脚本和样式，避免直接允许<code>&#39;unsafe-inline&#39;</code>。</li></ul></li></ul></li><li><strong>CSP 配置需结合业务</strong>：例如允许<code>&#39;unsafe-eval&#39;</code>可能降低安全性，需评估必要性。</li></ul><h2 id="sql-注入攻击" tabindex="-1">SQL 注入攻击 <a class="header-anchor" href="#sql-注入攻击" aria-label="Permalink to &quot;SQL 注入攻击&quot;">​</a></h2><ul><li>攻击者通过输入恶意 SQL 代码，篡改数据库查询逻辑，窃取或破坏数据（如绕过登录、删库）。</li><li>如何防御 SQL 注入？前端能做哪些防护？ <ul><li><strong>防御方案</strong>： <ul><li><strong>参数化查询</strong>（预编译语句）：避免拼接 SQL 字符串（如使用<code>PreparedStatement</code>）。</li><li><strong>ORM 框架</strong>：使用 Sequelize、TypeORM 等，自动处理参数转义。</li><li><strong>最小权限原则</strong>：数据库账号限制为只读/必要操作权限。</li></ul></li><li><strong>前端辅助</strong>： <ul><li>输入合法性校验（如长度、格式），但不可依赖前端（攻击者可直接绕过）。</li></ul></li></ul></li><li><strong>SQL 注入防御重点在后端</strong>，但前端需辅助校验减少无效请求。</li></ul><h2 id="https-与中间人攻击" tabindex="-1">HTTPS 与中间人攻击 <a class="header-anchor" href="#https-与中间人攻击" aria-label="Permalink to &quot;HTTPS 与中间人攻击&quot;">​</a></h2><p>HTTPS 如何保证数据安全？前端需要注意什么？</p><ul><li><strong>原理</strong>：SSL/TLS 加密传输 + 证书验证身份</li><li><strong>前端注意</strong>： <ul><li>使用全站 HTTPS（避免混合内容）</li><li>设置 HSTS 响应头：<code>Strict-Transport-Security: max-age=31536000</code></li><li>避免在 URL 中传递敏感参数（可能被日志记录）</li></ul></li></ul><h2 id="cors-配置风险" tabindex="-1">CORS 配置风险 <a class="header-anchor" href="#cors-配置风险" aria-label="Permalink to &quot;CORS 配置风险&quot;">​</a></h2><p>如何安全配置跨域资源共享（CORS）？</p><ul><li>精确设置<code>Access-Control-Allow-Origin</code>（避免<code>*</code>）</li><li>限制<code>Access-Control-Allow-Methods</code>为必要方法</li><li>避免暴露敏感头：<code>Access-Control-Expose-Headers</code></li><li>预检请求缓存：<code>Access-Control-Max-Age</code></li></ul><h2 id="前端安全审计方案" tabindex="-1">前端安全审计方案 <a class="header-anchor" href="#前端安全审计方案" aria-label="Permalink to &quot;前端安全审计方案&quot;">​</a></h2><p>如何系统化提升项目安全性？</p><ul><li><strong>流程控制</strong>： <ul><li>代码审核：ESLint 安全规则（如<code>no-eval</code>）</li><li>依赖检查：<code>npm audit</code>/Snyk 扫描第三方包</li><li>CI/CD集成安全测试（如OWASP ZAP）</li></ul></li><li><strong>监控</strong>： <ul><li>实时日志分析异常请求</li><li>错误监控捕获XSS/CSRF攻击</li></ul></li><li><strong>应急</strong>：制定漏洞响应机制（如 CSP 紧急更新）</li></ul><h2 id="第三方脚本安全管理" tabindex="-1">第三方脚本安全管理 <a class="header-anchor" href="#第三方脚本安全管理" aria-label="Permalink to &quot;第三方脚本安全管理&quot;">​</a></h2><p>如何安全引入 Google Analytics 等第三方 JS？</p><ul><li>使用<code>Subresource Integrity</code>（SRI 哈希校验）<div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  integrity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha384-xxxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li>通过 CSP 限制<code>script-src</code>域名</li><li>异步加载 + 错误降级处理</li></ul><h2 id="jwt-安全存储方案" tabindex="-1">JWT 安全存储方案 <a class="header-anchor" href="#jwt-安全存储方案" aria-label="Permalink to &quot;JWT 安全存储方案&quot;">​</a></h2><p>前端如何安全存储 JWT Token？</p><ul><li><strong>存储位置</strong>： <ul><li>避免 localStorage（易 XSS 窃取） → 优先存 Cookie+<code>HttpOnly</code></li><li>敏感操作使用短期 Token</li></ul></li><li><strong>传输安全</strong>： <ul><li>仅通过 HTTPS 传输</li><li>避免 URL 参数传递</li></ul></li></ul><h2 id="前端加密" tabindex="-1">前端加密 <a class="header-anchor" href="#前端加密" aria-label="Permalink to &quot;前端加密&quot;">​</a></h2><p>在前端用 JS 加密密码是否有效？为什么？</p><ul><li><strong>无效</strong>：前端代码透明，加密密钥易泄露（中间人可替换 JS）</li><li><strong>正确方案</strong>： <ul><li>使用 HTTPS 传输明文</li><li>敏感数据加盐哈希（后端处理）</li></ul></li></ul><h2 id="设计一个安全登录流程" tabindex="-1">设计一个安全登录流程 <a class="header-anchor" href="#设计一个安全登录流程" aria-label="Permalink to &quot;设计一个安全登录流程&quot;">​</a></h2><ol><li>输入：限制密码错误次数（防暴力破解）</li><li>传输：HTTPS + 验证码（防中间人/机器人）</li><li>存储：后端加盐哈希（如 bcrypt）</li><li>会话：短期 JWT Token + Refresh Token 轮换</li><li>监控：异常登录检测（IP/设备变更）</li></ol>`,31)])])}const g=l(t,[["render",o]]);export{u as __pageData,g as default};
